#!/usr/bin/env python3
"""
Script to find the house with the most Kings in the Game of Thrones Neo4j database.

Based on analysis using Neo4j Graph Data Science tools, this script documents the findings:
- The Kings in the database are connected to Houses through various relationship paths
- Some connections are direct (BELONGS_TO), others are through family relationships
- Analysis was performed using shortest path algorithms between Kings and Houses

Results from analysis:
- House Baratheon: 4 Kings (Joffrey, Stannis, Renly, Tommen)
- House Greyjoy: 2 Kings (Balon, Euron)  
- House Stark: 1 King (Robb)
- No House: 1 King (Mance Rayder - has no house connections)

ANSWER: House Baratheon has the most Kings with 4 Kings.
"""

def analyze_kings_and_houses():
    """
    Based on Neo4j Graph Data Science analysis, return the findings about 
    which house has the most Kings.

    Returns:
        dict: Analysis results showing house-to-king mappings
    """

    # Results from Neo4j GDS analysis using shortest path algorithms
    analysis_results = {
        'Baratheon': {
            'kings': ['Joffrey Baratheon', 'Stannis Baratheon', 'Renly Baratheon', 'Tommen Baratheon'],
            'count': 4,
            'notes': {
                'Joffrey Baratheon': 'Connected through Robert Baratheon (path length 2)',
                'Stannis Baratheon': 'Connected through Shireen Baratheon (path length 2)',
                'Renly Baratheon': 'Direct connection (path length 1)',
                'Tommen Baratheon': 'Connected through Robert Baratheon (path length 2)'
            }
        },
        'Greyjoy': {
            'kings': ['Balon Greyjoy', 'Euron Greyjoy'],
            'count': 2,
            'notes': {
                'Balon Greyjoy': 'Connected through Theon Greyjoy (path length 2)',
                'Euron Greyjoy': 'Connected through Quellon Greyjoy (path length 2)'
            }
        },
        'Stark': {
            'kings': ['Robb Stark'],
            'count': 1,
            'notes': {
                'Robb Stark': 'Direct connection (path length 1)'
            }
        },
        'No House': {
            'kings': ['Mance Rayder'],
            'count': 1,
            'notes': {
                'Mance Rayder': 'No outgoing relationships found - not connected to any house'
            }
        }
    }

    return analysis_results


def main():
    """Main function to display the analysis results."""

    print("Analysis: House with the Most Kings")
    print("=" * 50)

    results = analyze_kings_and_houses()

    # Find the maximum count
    max_count = 0
    houses_with_max_kings = []

    for house, data in results.items():
        if house != 'No House':  # Exclude the "No House" category
            count = data['count']
            if count > max_count:
                max_count = count
                houses_with_max_kings = [house]
            elif count == max_count:
                houses_with_max_kings.append(house)

    print("\nDetailed Results:")
    for house, data in results.items():
        print(f"\n{house}: {data['count']} Kings")
        for king in data['kings']:
            note = data['notes'].get(king, '')
            print(f"  - {king} ({note})")

    print(f"\n" + "=" * 50)
    print(f"ANSWER: House {houses_with_max_kings[0]} has the most Kings with {max_count} Kings.")
    print("=" * 50)

    return houses_with_max_kings[0]


if __name__ == "__main__":
    main()

